  void writeVariableDeclaration(VariableDeclaration node, Bool useVarKeyword) {
    {
      if (this->showOffsets) this->writeWord(dart_string("[") + node->fileOffset.toString() + dart_string("]"));
      if (this->showMetadata) this->writeMetadata(node);
      this->writeAnnotationList(node->annotations);
      this->writeModifier(node->isLowered, dart_string("lowered"));
      this->writeModifier(node->isLate, dart_string("late"));
      this->writeModifier(node->isRequired, dart_string("required"));
      this->writeModifier(node->isCovariantByDeclaration, dart_string("covariant-by-declaration"));
      this->writeModifier(node->isCovariantByClass, dart_string("covariant-by-class"));
      this->writeModifier(node->isFinal, dart_string("final"));
      this->writeModifier(node->isConst, dart_string("const"));
      this->writeModifier(node->isSynthesized && !((node->name == nullptr)), dart_string("synthesized"));
      this->writeModifier(node->isHoisted, dart_string("hoisted"));
      this->writeModifier(node->isWildcard, dart_string("wildcard"));
      auto hasImplicitInitializer = dart_is<NullLiteral>(node->initializer) || dart_is<ConstantExpression>(node->initializer) && dart_is<NullConstant>(dart_cast<ConstantExpression>(node->initializer)->constant);
      if ((node->initializer == nullptr) || hasImplicitInitializer && node->hasDeclaredInitializer) {
      this->writeModifier(node->hasDeclaredInitializer, dart_string("has-declared-initializer"));
} else if (!((node->initializer == nullptr)) && !(hasImplicitInitializer) && !(node->hasDeclaredInitializer)) {
      this->writeModifier(node->hasDeclaredInitializer, dart_string("has-no-declared-initializer"));
}
      this->writeAnnotatedType(node->type, ([&]() { Annotator let_var = this->annotator; return (let_var == nullptr) ? nullptr : let_var->annotateVariable(this, node); })());
      this->writeWord(this->getVariableName(node));
      auto initializer = node->initializer;
      if (!((initializer == nullptr))) {
      this->writeSpaced(dart_string("="));
      this->writeExpression(initializer);
}
}
  }
  
