  void writeNullability(Nullability nullability, Bool inComment) {
    {
      label_209034: switch (nullability) {
  case ObjectPtr<Nullability>::createConst():
    {
      this->writeSymbol(dart_string("*"));
      if (!(inComment)) {
      this->state = Printer::WORD;
}
      break;
}
  case ObjectPtr<Nullability>::createConst():
    {
      this->writeSymbol(dart_string("?"));
      if (!(inComment)) {
      this->state = Printer::WORD;
}
      break;
}
  case ObjectPtr<Nullability>::createConst():
    {
      this->writeSymbol(dart_string("%"));
      if (!(inComment)) {
      this->state = Printer::WORD;
}
      break;
}
  case ObjectPtr<Nullability>::createConst():
    {
      if (inComment) {
      this->writeSymbol(dart_string("!"));
}
      break;
}
}
}
  }
  
