  Bool isTop(DartType type) {
    {
      if (dart_is<InvalidType>(type)) return dart_bool(false);
      if (dart_is<DynamicType>(type)) return dart_bool(true);
      if (dart_is<VoidType>(type)) return dart_bool(true);
      if ((type->declaredNullability == ObjectPtr<Nullability>::createConst()) || (type->declaredNullability == ObjectPtr<Nullability>::createConst())) {
      auto nonNullableType = unwrapNullabilityConstructor(type);
      if (!(identical(type, nonNullableType))) {
      return this->isTop(nonNullableType) || this->isObject(nonNullableType);
}
}
      if (dart_is<FutureOrType>(type)) {
      return this->isTop(type->typeArgument);
}
      return dart_bool(false);
}
  }
  
