// ============================================================================

class GeneratedTypeConstraint {
public:
  Any typeParameter;
  Any constraint;
  Bool isUpper;
  GeneratedTypeConstraint(Any typeParameter, Any constraint) : typeParameter(typeParameter), constraint(constraint), isUpper(dart_bool(false)) {
  }
  
  GeneratedTypeConstraint(Any typeParameter, Any constraint) : typeParameter(typeParameter), constraint(constraint), isUpper(dart_bool(true)) {
  }
  
  String toString() {
    {
      return this->isUpper ? dart_string("<type> <: ") + this->constraint.toString() : this->constraint.toString() + dart_string(" <: <type>");
}
  }
  
};

// ============================================================================
// 类: MergedTypeConstraint
// ============================================================================

class MergedTypeConstraint {
public:
  Any lower;
  Any upper;
  TypeConstraintOrigin origin;
  MergedTypeConstraint(Any lower, Any upper, TypeConstraintOrigin origin) : lower(lower), upper(upper), origin(origin) {
  }
  
  MergedTypeConstraint(String typeParameterName, Any boundType, Any extendsType, TypeAnalyzerOperations typeAnalyzerOperations) {
  }
  
  MergedTypeConstraint clone() {
    {
      return ObjectPtr<MergedTypeConstraint>(new MergedTypeConstraint(/*lower:*/ this->lower, /*upper:*/ this->upper, /*origin:*/ this->origin));
}
  }
  
  Bool isEmpty(TypeAnalyzerOperations typeAnalyzerOperations) {
    {
      return dart_is<SharedUnknownType>(this->lower) && dart_is<SharedUnknownType>(this->upper);
}
  }
  
  Bool isSatisfiedBy(Any type, TypeAnalyzerOperations typeAnalyzerOperations) {
    {
      return typeAnalyzerOperations->typeIsSubtypeOfTypeSchema(type, this->upper) && typeAnalyzerOperations->typeSchemaIsSubtypeOfType(this->lower, type);
}
  }
  
  void mergeIn(GeneratedTypeConstraint generatedTypeConstraint, TypeAnalyzerOperations typeAnalyzerOperations) {
    {
      if (generatedTypeConstraint->isUpper) {
      this->mergeInTypeSchemaUpper(generatedTypeConstraint->constraint, typeAnalyzerOperations);
} else {
      this->mergeInTypeSchemaLower(generatedTypeConstraint->constraint, typeAnalyzerOperations);
}
}
  }
  
  void mergeInTypeSchemaLower(Any constraint, TypeAnalyzerOperations typeAnalyzerOperations) {
    {
      this->lower = typeAnalyzerOperations->typeSchemaLub(this->lower, constraint);
}
  }
  
  void mergeInTypeSchemaUpper(Any constraint, TypeAnalyzerOperations typeAnalyzerOperations) {
    {
      this->upper = typeAnalyzerOperations->typeSchemaGlb(this->upper, constraint);
}
  }
  
  String toString() {
    {
      return this->lower.toString() + dart_string(" <: <type> <: ") + this->upper.toString();
}
  }
  
};

