class TypeConstraintFromArgument : public TypeConstraintOrigin {
public:
  Any argumentType;
  Any parameterType;
  String parameterName;
  String genericClassName;
  Bool isGenericClassInDartCore;
  TypeConstraintFromArgument(Any argumentType, Any parameterType, String parameterName, String genericClassName, Bool isGenericClassInDartCore) : argumentType(argumentType), parameterType(parameterType), parameterName(parameterName), genericClassName(genericClassName), isGenericClassInDartCore(isGenericClassInDartCore) {
  }
  
  List<String> formatError(TypeAnalyzerOperations typeAnalyzerOperations) {
    {
      String prefix;
      if ((this->genericClassName == dart_string("List")) || (this->genericClassName == dart_string("Map")) && this->isGenericClassInDartCore) {
      prefix = this->genericClassName.toString() + dart_string(" ") + this->parameterName.toString();
} else {
      prefix = dart_string("Parameter '") + this->parameterName.toString() + dart_string("'");
}
      return _GrowableList::_literal3(prefix, dart_string("declared as     '") + SharedTypeView|getDisplayString(this->parameterType).toString() + dart_string("'"), dart_string("but argument is '") + SharedTypeView|getDisplayString(this->argumentType).toString() + dart_string("'."));
}
  }
  
};

