// ============================================================================
// 类: _Contains
// ============================================================================

class _Contains : public Matcher {
private:
  Object _expected;
public:
  _Contains(Object _expected) : _expected(_expected) {
  }
  
  Bool matches(Object item, Map<Any, Any> matchState) {
    {
      auto expected = this->_expected;
      if (dart_is<String>(item)) {
      return dart_is<Pattern>(expected) && item->contains(expected);
} else if (dart_is<Iterable>(item)) {
      if (dart_is<Matcher>(expected)) {
      return item->any([&](Any e) { return expected->matches(e, matchState); });
} else {
      return item->contains(this->_expected);
}
} else if (dart_is<Map<Any, Any>>(item)) {
      return item->containsKey(this->_expected);
}
      return dart_bool(false);
}
  }
  
  Description describe(Description description) {
    return description->add(dart_string("contains "))->addDescriptionOf(this->_expected);
  }
  
  Description describeMismatch(Object item, Description mismatchDescription, Map<Any, Any> matchState, Bool verbose) {
    {
      if (dart_is<String>(item) || dart_is<Iterable>(item) || dart_is<Map<Any, Any>>(item)) {
      super::describeMismatch(item, mismatchDescription, matchState, verbose);
      mismatchDescription->add(dart_string("does not contain "))->addDescriptionOf(this->_expected);
      return mismatchDescription;
} else {
      return mismatchDescription->add(dart_string("is not a string, map or iterable"));
}
}
  }
  
};

