// 类: NnbdTopMergeVisitor
// ============================================================================

class NnbdTopMergeVisitor : public MergeVisitor {
public:
  CoreTypes coreTypes;
  NnbdTopMergeVisitor(CoreTypes coreTypes) : coreTypes(coreTypes) {
  }
  
  Nullability mergeNullability(Nullability a, Nullability b) {
    {
      if ((a == b)) {
      return a;
} else if ((a == ObjectPtr<Nullability>::createConst())) {
      return b;
} else if ((b == ObjectPtr<Nullability>::createConst())) {
      return a;
}
      return nullptr;
}
  }
  
  DartType visitInterfaceType(InterfaceType a, DartType b) {
    {
      if ((a == this->coreTypes->objectNullableRawType)) {
      if (dart_is<DynamicType>(b)) {
      return this->coreTypes->objectNullableRawType;
} else if (dart_is<VoidType>(b)) {
      return this->coreTypes->objectNullableRawType;
} else if ((b == this->coreTypes->objectNullableRawType)) {
      return this->coreTypes->objectNullableRawType;
}
} else if ((a == this->coreTypes->objectLegacyRawType)) {
      if (dart_is<DynamicType>(b)) {
      return this->coreTypes->objectNullableRawType;
} else if (dart_is<VoidType>(b)) {
      return this->coreTypes->objectNullableRawType;
}
}
      return super::visitInterfaceType(a, b);
}
  }
  
  DartType visitVoidType(VoidType a, DartType b) {
    {
      if (dart_is<DynamicType>(b)) {
      return this->coreTypes->objectNullableRawType;
} else if (dart_is<VoidType>(b)) {
      return ObjectPtr<VoidType>::createConst();
} else if ((b == this->coreTypes->objectNullableRawType)) {
      return this->coreTypes->objectNullableRawType;
} else if ((b == this->coreTypes->objectLegacyRawType)) {
      return this->coreTypes->objectNullableRawType;
}
      return super::visitVoidType(a, b);
}
  }
  
  DartType visitDynamicType(DynamicType a, DartType b) {
    {
      if (dart_is<DynamicType>(b)) {
      return ObjectPtr<DynamicType>::createConst();
} else if (dart_is<VoidType>(b)) {
      return this->coreTypes->objectNullableRawType;
} else if ((b == this->coreTypes->objectNullableRawType)) {
      return this->coreTypes->objectNullableRawType;
} else if ((b == this->coreTypes->objectLegacyRawType)) {
      return this->coreTypes->objectNullableRawType;
}
      return super::visitDynamicType(a, b);
}
  }
  
  DartType visitNeverType(NeverType a, DartType b) {
    {
      if ((a->nullability == ObjectPtr<Nullability>::createConst()) && dart_is<NullType>(b)) {
      return ObjectPtr<NullType>::createConst();
}
      return super::visitNeverType(a, b);
}
  }
  
  DartType visitNullType(NullType a, DartType b) {
    {
      if (dart_is<NeverType>(b) && (b->nullability == ObjectPtr<Nullability>::createConst())) {
      return ObjectPtr<NullType>::createConst();
}
      return super::visitNullType(a, b);
}
  }
  
};

// ============================================================================
// 类: _Norm
// ============================================================================

class _Norm : public ReplacementVisitor {
public:
  CoreTypes coreTypes;
  _Norm(CoreTypes coreTypes) : coreTypes(coreTypes) {
  }
  
  DartType visitInterfaceType(InterfaceType node, Variance variance) {
    {
      return ([&]() { DartType let_var = super::visitInterfaceType(node, variance); return (let_var == nullptr) ? nullptr : let_var->withDeclaredNullability(node->nullability); })();
}
  }
  
  DartType visitFutureOrType(FutureOrType node, Variance variance) {
    {
      auto typeArgument = node->typeArgument;
      typeArgument = ([&]() { DartType let_var = typeArgument->accept1(this, variance); return (let_var == nullptr) ? typeArgument : let_var; })();
      if (this->coreTypes->isTop(typeArgument)) {
      assert(((typeArgument->nullability == ObjectPtr<Nullability>::createConst()) || (typeArgument->nullability == ObjectPtr<Nullability>::createConst())).toBool());
      return typeArgument;
} else if (dart_is<InterfaceType>(typeArgument) && (typeArgument->classNode == this->coreTypes->objectClass) && (typeArgument->nullability == ObjectPtr<Nullability>::createConst())) {
      assert((!(this->coreTypes->isTop(typeArgument))).toBool());
      return typeArgument->withDeclaredNullability(node->nullability);
} else if (dart_is<NeverType>(typeArgument) && (typeArgument->nullability == ObjectPtr<Nullability>::createConst())) {
      assert((!(this->coreTypes->isTop(typeArgument))).toBool());
      assert((!(this->coreTypes->isObject(typeArgument))).toBool());
      return ObjectPtr<InterfaceType>(new InterfaceType(this->coreTypes->futureClass, node->nullability, _GrowableList::_literal1(typeArgument)));
} else if (this->coreTypes->isNull(typeArgument)) {
      assert((!(this->coreTypes->isTop(typeArgument))).toBool());
      assert((!(this->coreTypes->isObject(typeArgument))).toBool());
      assert((!(this->coreTypes->isBottom(typeArgument))).toBool());
      return ObjectPtr<InterfaceType>(new InterfaceType(this->coreTypes->futureClass, uniteNullabilities(typeArgument->nullability, node->nullability), _GrowableList::_literal1(typeArgument)));
}
      assert((!(this->coreTypes->isTop(typeArgument))).toBool());
      assert((!(this->coreTypes->isObject(typeArgument))).toBool());
      assert((!(this->coreTypes->isBottom(typeArgument))).toBool());
      assert((!(this->coreTypes->isNull(typeArgument))).toBool());
      return ObjectPtr<FutureOrType>(new FutureOrType(typeArgument, node->nullability));
}
  }
  
  DartType visitTypeParameterType(TypeParameterType node, Variance variance) {
    {
      auto bound = node->parameter->bound;
      if (this->normalizesToNever(bound)) {
      auto result = NeverType::fromNullability(node->nullability);
      return ([&]() { DartType let_var = result->accept1(this, variance); return (let_var == nullptr) ? result : let_var; })();
}
      assert((!(this->coreTypes->isBottom(bound))).toBool());
      return nullptr;
}
  }
  
  DartType visitStructuralParameterType(StructuralParameterType node, Variance variance) {
    {
      auto bound = node->parameter->bound;
      if (this->normalizesToNever(bound)) {
      auto result = NeverType::fromNullability(node->nullability);
      return ([&]() { DartType let_var = result->accept1(this, variance); return (let_var == nullptr) ? result : let_var; })();
}
      assert((!(this->coreTypes->isBottom(bound))).toBool());
      return nullptr;
}
  }
  
  DartType visitIntersectionType(IntersectionType node, Variance variance) {
    {
      auto right = node->right;
      right = ([&]() { DartType let_var = right->accept1(this, variance); return (let_var == nullptr) ? right : let_var; })();
      if (dart_is<NeverType>(right) && (right->nullability == ObjectPtr<Nullability>::createConst())) {
      return right;
} else if (this->coreTypes->isTop(right)) {
      assert((!(this->coreTypes->isBottom(right))).toBool());
      assert(((right->nullability == ObjectPtr<Nullability>::createConst())).toBool());
      return node->left;
} else if (dart_is<TypeParameterType>(right) && (right->parameter == node->left->parameter) && (right->declaredNullability == node->left->declaredNullability)) {
      assert((!(this->coreTypes->isBottom(right))).toBool());
      assert((!(this->coreTypes->isTop(right))).toBool());
      return node->left;
} else if ((right == this->coreTypes->objectNonNullableRawType) && (norm(this->coreTypes, node->left->parameter->bound) == this->coreTypes->objectNonNullableRawType)) {
      return node->left;
} else if (identical(right, node->right)) {
      return nullptr;
}
      return ObjectPtr<IntersectionType>(new IntersectionType(node->left, right));
}
  }
  
  DartType visitNeverType(NeverType node, Variance variance) {
    {
      if ((node->nullability == ObjectPtr<Nullability>::createConst())) return ObjectPtr<NullType>::createConst();
      return nullptr;
}
  }
  
  Bool normalizesToNever(DartType type) {
    {
      if (dart_is<NeverType>(type) && (type->nullability == ObjectPtr<Nullability>::createConst())) {
      return dart_bool(true);
} else if (dart_is<TypeParameterType>(type)) {
      return this->normalizesToNever(type->parameter->bound);
} else if (dart_is<IntersectionType>(type)) {
      return this->normalizesToNever(type->right);
}
      return dart_bool(false);
}
  }
  
};

