String formatFailure(Matcher expected, Object actual, String which, String reason) {
  {
    auto buffer = ObjectPtr<StringBuffer>(new StringBuffer());
    buffer->writeln(indent(prettyPrint(expected)));
    buffer->writeln(indent(prettyPrint(actual)));
    if (which->isNotEmpty) buffer->writeln(indent(which));
    if (!((reason == nullptr))) buffer->writeln(reason);
    return buffer->toString();
}
}

