Any _postResponse(SendPort replyPort, Object id, ServiceExtensionResponse response, Bool trace_service) {
  {
    assert((!((replyPort == nullptr))).toBool());
    if ((id == nullptr)) {
    if (trace_service) {
    dart_print(dart_string("vm-service: posting no response for request"));
}
    replyPort->send(nullptr);
    return;
}
    assert((!((id == nullptr))).toBool());
    auto sb = ObjectPtr<StringBuffer>(new StringBuffer());
    sb->write(dart_string("{\"jsonrpc\":\"2.0\","));
    if (response->isError()) {
    if (trace_service) {
    dart_print(dart_string("vm-service: posting error response for request ") + id.toString());
}
    sb->write(dart_string("\"error\":"));
} else {
    if (trace_service) {
    dart_print(dart_string("vm-service: posting response for request ") + id.toString());
}
    sb->write(dart_string("\"result\":"));
}
    sb->write(response->_toString().toString() + dart_string(","));
    if (dart_is<String>(id)) {
    sb->write(dart_string("\"id\":\"") + id.toString() + dart_string("\"}"));
} else {
    sb->write(dart_string("\"id\":") + id.toString() + dart_string("}"));
}
    replyPort->send(sb->toString());
}
}

