void _iterablePartsToStrings(Iterable iterable, List<String> parts) {
  {
    auto length = dart_int(0);
    auto count = dart_int(0);
    auto it = iterable->iterator;
    while ((length < dart_int(80)) || (count < dart_int(3))) {
    if (!(it->moveNext())) return;
    auto next = it->current.toString();
    parts->add(next);
    length = (length + (next->length + dart_int(2)));
    count = (count + dart_int(1));
}
    String penultimateString;
    String ultimateString;
    if (!(it->moveNext())) {
    if ((count <= (dart_int(3) + dart_int(2)))) return;
    ultimateString = parts->removeLast();
    penultimateString = parts->removeLast();
} else {
    auto penultimate = it->current;
    count = (count + dart_int(1));
    if (!(it->moveNext())) {
    if ((count <= (dart_int(3) + dart_int(1)))) {
    parts->add(penultimate.toString());
    return;
}
    ultimateString = penultimate.toString();
    penultimateString = parts->removeLast();
    length = (length + (ultimateString->length + dart_int(2)));
} else {
    auto ultimate = it->current;
    count = (count + dart_int(1));
    assert(((count < dart_int(100))).toBool());
    while (it->moveNext()) {
    penultimate = ultimate;
    ultimate = it->current;
    count = (count + dart_int(1));
    if ((count > dart_int(100))) {
    while ((length > ((dart_int(80) - dart_int(3)) - dart_int(2))) && (count > dart_int(3))) {
    length = (length - (parts->removeLast()->length + dart_int(2)));
    count = (count - dart_int(1));
}
    parts->add(dart_string("..."));
    return;
}
}
    penultimateString = penultimate.toString();
    ultimateString = ultimate.toString();
    length = (length + ((ultimateString->length + penultimateString->length) + (dart_int(2) * dart_int(2))));
}
}
    String elision;
    if ((count > (parts->length + dart_int(2)))) {
    elision = dart_string("...");
    length = (length + (dart_int(3) + dart_int(2)));
}
    while ((length > dart_int(80)) && (parts->length > dart_int(3))) {
    length = (length - (parts->removeLast()->length + dart_int(2)));
    if ((elision == nullptr)) {
    elision = dart_string("...");
    length = (length + (dart_int(3) + dart_int(2)));
}
}
    if (!((elision == nullptr))) {
    parts->add(elision);
}
    parts->add(penultimateString);
    parts->add(ultimateString);
}
}

